"""Rule-based PII redactor improved for SSNs, emails, phones, and credit cards."""
import re

PATTERNS = [
    ("EMAIL", re.compile(r"[\w.]+@[\w]+\.\w+|[\w.]+\s*\[at\]\s*[\w.]+\s*\[dot\]\s*\w+", re.IGNORECASE)),
    ("PHONE", re.compile(r"""
        (?:(?:\+?1\s*(?:[.-]\s*)?)?(?:\(\s*([2-9]0[1-9]|[2-9][1-9]0|[2-9][1-9][1-9])\s*\)|([2-9]0[1-9]|[2-9][1-9]0|[2-9][1-9][1-9]))\s*(?:[.-]\s*)?)?
        ([2-9]0[1-9]|[2-9][1-9]0|[2-9][1-9][1-9])\s*(?:[.-]\s*)?
        ([0-9]{4})
        (?:\s*(?:ext|x|extension)\s*\.?\s*([0-9]+))?
    """, re.VERBOSE)),
    ("SSN", re.compile(r"""
        (?:
            \b(?:ssn|social\s+security\s+(?:number|no\.?))\b[:\s]*
            ([0-9]{3}[-\s]?[0-9]{2}[-\s]?[0-9]{4})\b
        ) | (?:
            \b(?!(?:\d{3}-\d{2}-\d{4})(?:-|$))\d{3}[-\s]\d{2}[-\s]\d{4}\b
        )
    """, re.VERBOSE | re.IGNORECASE)),
    ("CREDIT_CARD", re.compile(r"\b(?:\d[ -]*){13,16}\b")),
]


def luhn_check(card_num: str) -> bool:
    digits = [int(c) for c in card_num if c.isdigit()]
    if not (13 <= len(digits) <= 16):
        return False
    checksum = 0
    reverse_digits = digits[::-1]
    for i, d in enumerate(reverse_digits):
        if i % 2 == 1:
            d *= 2
            if d > 9:
                d -= 9
        checksum += d
    return checksum % 10 == 0


def find_pii(text):
    """Return a list of (start, end, label) spans that contain PII."""
    spans = []

    # 1. Emails, Phones, SSNs
    for label, pattern in PATTERNS:
        if label == "CREDIT_CARD":
            continue
        for m in pattern.finditer(text):
            # If matched via group(1) in SSN pattern, adjust start/end to group(1)
            if label == "SSN" and m.lastindex and m.group(1):
                start = m.start(1)
                end = m.end(1)
            else:
                start, end = m.start(), m.end()
            spans.append((start, end, label))

    # 2. Credit Cards with Luhn validation
    cc_pattern = PATTERNS[3][1]
    for m in cc_pattern.finditer(text):
        candidate = m.group(0)
        if luhn_check(candidate):
            spans.append((m.start(), m.end(), "CREDIT_CARD"))

    # Resolve overlapping spans by keeping the longer/earlier ones
    spans.sort(key=lambda x: (x[0], -(x[1] - x[0])))
    filtered = []
    last_end = 0
    for start, end, label in spans:
        if start >= last_end:
            filtered.append((start, end, label))
            last_end = end
    return filtered
